// Command gen generates Seaport's permission code from iam/permissions.json:
// internal/permission/permission_gen.go and web/src/lib/permissions.gen.ts.
// It refuses an invalid manifest (format, prefix, duplicates, roles outside
// the catalog, an Admin role that misses a permission).
//
// Run through `go generate ./internal/permission`. The test in this package
// fails when the generated files are stale.
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

const (
	manifestPath = "iam/permissions.json"
	goPath       = "internal/permission/permission_gen.go"
	tsPath       = "web/src/lib/permissions.gen.ts"
	header       = "Code generated by internal/permission/gen from iam/permissions.json; DO NOT EDIT."
	// adminRole must hold the whole catalog: none and token mode admins
	// hold every permission, so the iam role of the same name does too.
	adminRole = "Admin"
)

var permissionName = regexp.MustCompile(`^[a-z0-9]+:[a-z0-9-]+:[a-z0-9-]+$`)

type manifest struct {
	Resource struct {
		Name   string `json:"name"`
		Prefix string `json:"prefix"`
	} `json:"resource"`
	Permissions []struct {
		Name  string `json:"name"`
		Label string `json:"label"`
	} `json:"permissions"`
	Roles []struct {
		Name        string   `json:"name"`
		Permissions []string `json:"permissions"`
	} `json:"roles"`
}

func main() {
	root := flag.String("root", ".", "repository root")
	flag.Parse()
	files, err := generate(*root)
	if err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		os.Exit(1)
	}
	for path, content := range files {
		if err := os.WriteFile(filepath.Join(*root, path), content, 0o644); err != nil {
			fmt.Fprintln(os.Stderr, "gen:", err)
			os.Exit(1)
		}
	}
}

// generate reads and checks the manifest under root and returns the
// generated files by repository-relative path.
func generate(root string) (map[string][]byte, error) {
	raw, err := os.ReadFile(filepath.Join(root, manifestPath))
	if err != nil {
		return nil, err
	}
	return generateFrom(raw)
}

func generateFrom(raw []byte) (map[string][]byte, error) {
	var m manifest
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&m); err != nil {
		return nil, fmt.Errorf("%s: %w", manifestPath, err)
	}
	if err := m.check(); err != nil {
		return nil, fmt.Errorf("%s: %w", manifestPath, err)
	}
	goSrc, err := m.goSource()
	if err != nil {
		return nil, err
	}
	return map[string][]byte{goPath: goSrc, tsPath: m.tsSource()}, nil
}

func (m manifest) check() error {
	prefix := m.Resource.Prefix
	if prefix == "" || m.Resource.Name == "" {
		return fmt.Errorf("resource needs a name and a prefix")
	}
	if len(m.Permissions) == 0 {
		return fmt.Errorf("no permissions")
	}
	catalog := map[string]bool{}
	idents := map[string]string{}
	for _, p := range m.Permissions {
		switch {
		case !permissionName.MatchString(p.Name):
			return fmt.Errorf("permission %q: want <prefix>:<entity>:<action> in lowercase", p.Name)
		case !strings.HasPrefix(p.Name, prefix+":"):
			return fmt.Errorf("permission %q: must start with %q (IAMKit enforces the resource prefix)", p.Name, prefix+":")
		case catalog[p.Name]:
			return fmt.Errorf("permission %q is listed twice", p.Name)
		case strings.TrimSpace(p.Label) == "":
			return fmt.Errorf("permission %q has no label", p.Name)
		}
		catalog[p.Name] = true
		id := ident(p.Name)
		if other, ok := idents[id]; ok {
			return fmt.Errorf("permissions %q and %q both become %s", other, p.Name, id)
		}
		idents[id] = p.Name
	}
	roles := map[string]bool{}
	for _, r := range m.Roles {
		if r.Name == "" || roles[r.Name] {
			return fmt.Errorf("role %q: names must be set and unique", r.Name)
		}
		roles[r.Name] = true
		if len(r.Permissions) == 0 {
			return fmt.Errorf("role %q has no permissions", r.Name)
		}
		held := map[string]bool{}
		for _, p := range r.Permissions {
			if !catalog[p] {
				return fmt.Errorf("role %q: %q is not in the catalog", r.Name, p)
			}
			if held[p] {
				return fmt.Errorf("role %q lists %q twice", r.Name, p)
			}
			held[p] = true
		}
		if r.Name == adminRole && len(held) != len(catalog) {
			return fmt.Errorf("role %q must hold every permission (token-mode admins do)", r.Name)
		}
	}
	if !roles[adminRole] {
		return fmt.Errorf("a role named %q is required", adminRole)
	}
	return nil
}

// ident turns seaport:crew-tokens:write into CrewTokensWrite.
func ident(name string) string {
	var b strings.Builder
	for _, part := range strings.Split(name, ":")[1:] {
		for _, word := range strings.Split(part, "-") {
			if word != "" {
				b.WriteString(strings.ToUpper(word[:1]) + word[1:])
			}
		}
	}
	return b.String()
}

func (m manifest) goSource() ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// %s\n\npackage permission\n\n", header)
	fmt.Fprintf(&b, "// Prefix of the IAMKit resource; every permission starts with it.\nconst Prefix = %q\n\n", m.Resource.Prefix)
	fmt.Fprintf(&b, "// ResourceName is the IAMKit resource's name.\nconst ResourceName = %q\n\n", m.Resource.Name)
	b.WriteString("// Permissions of the resource catalog.\nconst (\n")
	for _, p := range m.Permissions {
		fmt.Fprintf(&b, "\t%s = %q // %s\n", ident(p.Name), p.Name, p.Label)
	}
	b.WriteString(")\n\n// All is the whole catalog, in manifest order.\nvar All = []string{\n")
	for _, p := range m.Permissions {
		fmt.Fprintf(&b, "\t%s,\n", ident(p.Name))
	}
	b.WriteString("}\n\n// Labels say what each permission lets someone do.\nvar Labels = map[string]string{\n")
	for _, p := range m.Permissions {
		fmt.Fprintf(&b, "\t%s: %q,\n", ident(p.Name), p.Label)
	}
	b.WriteString("}\n\n// Roles on the resource, in manifest order.\nvar Roles = []Role{\n")
	for _, r := range m.Roles {
		fmt.Fprintf(&b, "\t{Name: %q, Permissions: []string{", r.Name)
		for i, p := range r.Permissions {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(ident(p))
		}
		b.WriteString("}},\n")
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

func (m manifest) tsSource() []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// %s\n\n", header)
	b.WriteString("/** Every permission of the Seaport resource, in manifest order. */\nexport const permissions = [\n")
	for _, p := range m.Permissions {
		fmt.Fprintf(&b, "  %s,\n", quote(p.Name))
	}
	b.WriteString("] as const\n\nexport type Permission = (typeof permissions)[number]\n\n")
	b.WriteString("/** Permissions by name (the Go constants' names): `can(Perm.DocksWrite)`. */\nexport const Perm = {\n")
	for _, p := range m.Permissions {
		fmt.Fprintf(&b, "  %s: %s,\n", ident(p.Name), quote(p.Name))
	}
	b.WriteString("} as const satisfies Record<string, Permission>\n\n")
	b.WriteString("/** What each permission lets someone do. */\nexport const permissionLabels: Record<Permission, string> = {\n")
	for _, p := range m.Permissions {
		fmt.Fprintf(&b, "  %s: %s,\n", quote(p.Name), quote(p.Label))
	}
	b.WriteString("}\n")
	return b.Bytes()
}

// quote renders a double-quoted TypeScript string (the web app's style).
func quote(s string) string {
	return `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(s) + `"`
}
